/* ===== hero rigs: jointed low-poly bodies (shoulder/elbow/hip/knee), per-hero masks, weapons, procedural animation ===== */
function taperGeo(wt, dt, wb, db, h) {
  const g = new THREE.BoxGeometry(1, h, 1), p = g.attributes.position;
  for (let i = 0; i < p.count; i++) { const top = p.getY(i) > 0; p.setX(i, p.getX(i) * (top ? wt : wb)); p.setZ(i, p.getZ(i) * (top ? dt : db)); }
  return g;
}
// part collector: everything added to one kit is merged into one lit mesh + one glow mesh
function kit() {
  const lit = [], glow = [];
  const add = (g, col, x, y, z, rx, ry, rz, sx, sy, sz) => { const m = TRS(x || 0, y || 0, z || 0, rx, ry, rz, sx, sy, sz); if (typeof col === 'object') glow.push({ g, m, c: col.g }); else lit.push({ g, m, c: col }); };
  const k = {
    b(w, h, d, col, x, y, z, rx, ry, rz) { add(new THREE.BoxGeometry(w, h, d), col, x, y, z, rx, ry, rz); return k; },
    t(wt, dt, wb, db, h, col, x, y, z, rx, ry, rz) { add(taperGeo(wt, dt, wb, db, h), col, x, y, z, rx, ry, rz); return k; },
    c(r, h, n, col, x, y, z, rx, ry, rz) { add(new THREE.ConeGeometry(r, h, n), col, x, y, z, rx, ry, rz); return k; },
    y(rt, rb, h, n, col, x, y, z, rx, ry, rz) { add(new THREE.CylinderGeometry(rt, rb, h, n), col, x, y, z, rx, ry, rz); return k; },
    o(r, col, x, y, z, sx, sy, sz, rx, ry, rz) { add(new THREE.OctahedronGeometry(r, 0), col, x, y, z, rx, ry, rz, sx || 1, sy || 1, sz || 1); return k; },
    i(r, col, x, y, z, d) { add(new THREE.IcosahedronGeometry(r, d || 0), col, x, y, z); return k; },
    into(group, mat, gmat) {
      if (lit.length) { const m = new THREE.Mesh(mergeParts(lit), mat); m.castShadow = true; group.add(m); }
      if (glow.length) group.add(new THREE.Mesh(mergeParts(glow), gmat));
    }
  };
  return k;
}
const HPI = Math.PI / 2, GUN_YAW = 0.32;   // gunners stand bladed: torso turned by GUN_YAW, weapon turned back so it still points ahead
// two-bone reach: orient an arm (shoulder group + elbow hinge, bones running along local -y) so the hand lands on target T.
// pole says which way the elbow should bulge. An out-of-reach target leaves the arm straight, pointing at it.
function aimArm(arm, fore, T, pole) {
  const l1 = 0.44, l2 = 0.47, d = new THREE.Vector3().subVectors(T, arm.position), len = Math.min(d.length(), l1 + l2 - 0.02), dir = d.clone().normalize();
  const A = Math.acos(clamp((l1 * l1 + len * len - l2 * l2) / (2 * l1 * len), -1, 1));
  const pp = pole.clone().addScaledVector(dir, -pole.dot(dir)).normalize();
  const up = dir.clone().multiplyScalar(Math.cos(A)).addScaledVector(pp, Math.sin(A)).normalize();            // upper arm
  const f = dir.clone().multiplyScalar(len).addScaledVector(up, -l1).normalize();                               // forearm
  const w = f.clone().addScaledVector(up, -f.dot(up)).normalize(), beta = Math.acos(clamp(f.dot(up), -1, 1));
  const y = up.clone().negate(), x = new THREE.Vector3().crossVectors(y, w).normalize();
  arm.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(x, y, w)); fore.rotation.set(-beta, 0, 0);
}

